import pytest, pandas as pd
from unittest.mock import patch, MagicMock

def filter_large(df, threshold=1000):
    return df[df['amount'] > threshold]

def test_filter_basic():
    df = pd.DataFrame({'id':[1,2,3], 'amount':[500,1500,200]})
    result = filter_large(df)
    assert len(result) == 1 and result.iloc[0]['id'] == 2

@pytest.mark.parametrize('amounts,threshold,expected', [
    ([500,1500,200], 1000, 1),
    ([1100,1200,1300], 1000, 3),
    ([50,100], 1000, 0),
])
def test_filter_param(amounts, threshold, expected):
    df = pd.DataFrame({'amount': amounts})
    assert len(filter_large(df, threshold)) == expected

